import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Montserrat');

// Module-level font loading ensures availability before frame 0
const { fontFamily } = loadFont();



export type BoldPopTextProps = Record<string, any>;

const BoldPopText: React.FC<BoldPopTextProps> = ({
  backgroundColor = "#071B36",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "$1,000,000",
  textColor = "#FFCA28", 
  extrusionColor = "#D49A00", 
  fontSize = 320,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Responsive scale factor for all sizes
  const s = Math.min(width, height) / 1080;

  // Parser safety for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate a solid 3D extrusion shadow dynamically based on canvas scale
  const shadowDepth = Math.round(20 * s);
  let shadowArray = [];
  for (let i = 1; i <= shadowDepth; i++) {
    // Drop the shadow straight down for a solid block feel
    shadowArray.push(`0px ${i}px 0px ${extrusionColor}`);
  }
  // Add a final soft drop shadow below the 3D block
  shadowArray.push(`0px ${shadowDepth + 20 * s}px ${30 * s}px rgba(0,0,0,0.5)`);
  const shadowString = shadowArray.join(", ");

  // Split text into an array to stagger the animation per character
  const characters = text.split("");

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "row",
        fontFamily,
        overflow: "hidden",
      }}
    >
      {characters.map((char, index) => {
        // Stagger entrance by 2 frames per character
        const delay = index * 2; 

        // Spring physics for the "pop" effect
        const pop = spring({
          frame: frame - delay,
          fps,
          config: {
            damping: 12,
            stiffness: 160,
            mass: 0.8,
          },
        });

        const scale = interpolate(pop, [0, 1], [0, 1]);
        
        // Slide up from below as it scales
        const translateY = interpolate(pop, [0, 1], [150 * s, 0]);

        // Ensure element is completely invisible before its entrance frame
        const opacity = interpolate(
          frame - delay,
          [0, 1],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        return (
          <div
            key={index}
            style={{
              display: "inline-block",
              fontSize: fontSize * s,
              fontWeight: 900,
              color: textColor,
              textShadow: shadowString,
              opacity,
              transform: `translateY(${translateY}px) scale(${scale})`,
              transition: "none", // Strict enforcement of frame-based animation
              margin: `0 ${char === " " ? 30 * s : 1 * s}px`, 
              lineHeight: 1,
            }}
          >
            {char === " " ? "\u00A0" : char}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default BoldPopText;